using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;
using UnityEngine.SceneManagement;
using Object=UnityEngine.Object;
namespace Wildfolk.Editor
{
 [InitializeOnLoad]public static class AudioProductionQa
 {
  private static string Root=>Environment.GetEnvironmentVariable("LOWFIRE_AUDIO_RESULTS")??throw new InvalidOperationException("Isolated audio results directory required");
  private static readonly List<string> checks=new List<string>();private static readonly Dictionary<Sound,int> cues=new Dictionary<Sound,int>();
  private static readonly float[] samples=new float[1024];private static double power;private static float peak;private static int buffers;
  static AudioProductionQa(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&UnityEditor.SessionState.GetBool("Lowfire.AudioQa.Run",false)){UnityEditor.SessionState.SetBool("Lowfire.AudioQa.Run",false);var host=new GameObject("Isolated audio verification").AddComponent<DevelopmentCoroutineHost>();Object.DontDestroyOnLoad(host.gameObject);host.StartCoroutine(Guard(Flow()));}};}
  public static void Run(){Directory.CreateDirectory(Root);Directory.CreateDirectory(Environment.GetEnvironmentVariable("LOWFIRE_ECONOMY_RESULTS"));UnityEditor.SessionState.SetString("Wildfolk.QA.Directory",Path.Combine(Path.GetTempPath(),"LowfireAudioQA",Guid.NewGuid().ToString("N")));UnityEditor.SessionState.SetBool("Lowfire.AudioQa.Run",true);EditorSceneManagerOpen();Application.runInBackground=true;EditorApplication.isPlaying=true;}
  private static void EditorSceneManagerOpen()=>UnityEditor.SceneManagement.EditorSceneManager.OpenScene(FrontendSceneBuilder.ScenePath);
  private static IEnumerator Guard(IEnumerator flow)
  {
   var stack=new Stack<IEnumerator>();stack.Push(flow);while(stack.Count>0){bool more;object current;try{more=stack.Peek().MoveNext();current=more?stack.Peek().Current:null;}catch(Exception ex){AudioRuntime.Played-=Heard;File.WriteAllText(Path.Combine(Root,"actual-failed.txt"),ex.ToString());EditorApplication.Exit(1);yield break;}if(!more){stack.Pop();continue;}if(current is IEnumerator inner)stack.Push(inner);else yield return current;}
   AudioRuntime.Played-=Heard;var r=AudioRuntime.Current;var clips=r.Bank.Sounds.SelectMany(e=>e.Clips).Concat(r.Bank.MusicBeds).Concat(r.Bank.EnvironmentBeds).Append(r.Bank.Fire).Distinct().ToArray();
   File.WriteAllText(Path.Combine(Root,"actual.json"),JsonUtility.ToJson(new Result{Passed=true,Checks=checks.ToArray(),Cues=cues.Select(x=>x.Key+"="+x.Value).ToArray(),Sources=r.GetComponentsInChildren<AudioSource>().Length,ClipEditorMemory=clips.Sum(c=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(c)),OutputPeak=peak,OutputRMS=buffers==0?0:Math.Sqrt(power/(buffers*samples.Length)),OutputBuffers=buffers,DeviceListeningApproved=false},true));EditorApplication.Exit(0);
  }
  [Serializable]private sealed class Result{public bool Passed,DeviceListeningApproved;public string[] Checks,Cues;public int Sources,OutputBuffers;public long ClipEditorMemory;public float OutputPeak;public double OutputRMS;}
  private static void Check(bool ok,string label){checks.Add((ok?"PASS ":"FAIL ")+label);File.WriteAllLines(Path.Combine(Root,"actual-checks.txt"),checks);if(!ok)throw new InvalidOperationException(label);}
  private static void Heard(Sound sound){cues.TryGetValue(sound,out var n);cues[sound]=n+1;}
  private static IEnumerator Wait(float seconds)
  {var end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end){AudioListener.GetOutputData(samples,0);foreach(var v in samples){power+=v*v;peak=Mathf.Max(peak,Mathf.Abs(v));}buffers++;yield return null;}}
  private static int Count(Sound sound)=>cues.TryGetValue(sound,out var n)?n:0;
  private static IEnumerator Flow()
  {
   yield return null;yield return null;AudioRuntime.Played+=Heard;var runtime=AudioRuntime.Current;Check(runtime!=null&&DevelopmentProfile.Isolated,"Main Menu has isolated audio owner");AudioRuntime.Play(Sound.UiConfirm);yield return Wait(2);Check(Object.FindObjectsByType<AudioListener>(FindObjectsSortMode.None).Length==1,"single camera listener");
   var home=Object.FindFirstObjectByType<HomeScreen>();foreach(var lang in new[]{"ko","en"})foreach(var size in new[]{new Vector2Int(1920,1080),new Vector2Int(1280,720),new Vector2Int(844,390)}){home.OpenSettings();L.SetLanguage(lang);yield return EconomyQa.Frame(home.Settings,size,"audio-settings-"+lang);home.ShowHome();}
   var prefs=Object.FindFirstObjectByType<UserPreferences>();prefs.SetMaster(0);yield return Wait(.15f);Check(runtime.GetComponentsInChildren<AudioSource>().All(s=>s.mute),"zero Master mutes all source categories");prefs.ResetDefaults();yield return Wait(.2f);
   SceneFlow.Repository=SaveRepository.Default();yield return SceneManager.LoadSceneAsync(SceneFlow.GameplayScene);yield return null;yield return null;ContentExpansionQa.Prepare();var save=ContentExpansionQa.S;var player=save.Player;var commands=player.GetComponent<PlayerInputCommands>();var input=player.GetComponent<PlayerInputAdapter>();input.enabled=false;
   player.GetComponent<PlayerMotor>().enabled=true;commands.SetMove(Vector2.right);yield return Wait(1.5f);commands.SetMove(Vector2.zero);player.GetComponent<PlayerMotor>().enabled=false;Check(Count(Sound.StepGrass)+Count(Sound.StepStone)>0,"real movement generated distance-based footsteps");
   foreach(var kind in new[]{ResourceKind.Wood,ResourceKind.Stone}){var node=Object.FindObjectsByType<ResourceNode>(FindObjectsSortMode.None).First(n=>n.Definition.Kind==kind);ContentExpansionQa.Move((Vector2)node.transform.position+Vector2.down*2);yield return Wait(.3f);node.Health.ApplyDamage(1,true,player);yield return Wait(.15f);}Check(Count(Sound.WoodHit)>0&&Count(Sound.StoneHit)>0,"wood and stone actual damage use distinct material cues");
   ContentExpansionQa.Move(Vector2.zero);ContentExpansionQa.OpenBench();var recipe=save.Catalog.Recipes.First(r=>r.RequiredStation==StationKind.Workbench&&r.RequiredWorkbenchTier==1&&r.ProcessingSeconds==0);ContentExpansionQa.Craft(recipe.Id);yield return Wait(.2f);Check(Count(Sound.CraftComplete)>0,"actual crafting result cue");commands.Session.CloseInventory();
   var placement=player.GetComponent<PlayerPlacement>();ContentExpansionQa.Select("campfire");player.GetComponent<PlayerAvatar>().Facing.Face(Vector2.right);var built=false;for(var x=-4;x<=8&&!built;x+=2){var target=new Vector2(x,4);ContentExpansionQa.Move(target-Vector2.right*placement.Settings.PlacementDistance);ContentExpansionQa.Clear(target,2);if(placement.CanPlaceAt(player.GetComponent<PlayerEquipment>().ActivePlaceable,target))built=placement.TryPlace();}Check(built,"actual placement committed");yield return Wait(.3f);Check(Count(Sound.Place)>0,"successful build cue");
   var fire=WorldPlaceable.Active.First(p=>p.PlayerBuilt&&p.Definition.Station==StationKind.Campfire).GetComponent<CraftingStation>();ContentExpansionQa.Move((Vector2)fire.transform.position+Vector2.left*2);player.GetComponent<PlayerCrafting>().OpenStation(fire);var cooked=save.Catalog.Recipes.First(r=>r.RequiredStation==StationKind.Campfire&&r.ProcessingSeconds>0);var completed=Count(Sound.CraftComplete);ContentExpansionQa.Craft(cooked.Id);yield return Wait(.2f);var processing=fire.GetComponent<StationProcessing>();Check(processing.IsBusy,"actual processing recipe queued");processing.Advance(cooked.ProcessingSeconds+1);yield return Wait(.2f);Check(processing.IsReady&&Count(Sound.CraftComplete)>completed,"processing timer completion cue");Check(processing.Collect(player),"actual cooked output collected");commands.Session.CloseInventory();
   var hp=player.GetComponent<Health>();hp.ApplyDamage(2,true);yield return Wait(.2f);Check(Count(Sound.PlayerHurt)>0,"actual player damage cue");ContentExpansionQa.Select("steel_sword");commands.Attack();yield return Wait(.6f);Check(Count(Sound.Blade)>0,"accepted blade swing cue");
   var survival=player.GetComponent<PlayerSurvival>();survival.Model.SetMeters(40,40);ContentExpansionQa.Select("berry");Check(survival.TryConsume(),"actual food consumed");yield return Wait(.2f);Check(Count(Sound.Eat)>0,"food confirmation cue");ContentExpansionQa.Select("clean_water_cup");Check(survival.TryConsume(),"actual clean water consumed");yield return Wait(.2f);Check(Count(Sound.Drink)>0,"drink confirmation cue");
   var pond=save.World.Map.PondCenter;ContentExpansionQa.Move(pond+Vector2.right*(save.World.Map.PondRadius.x+1));ContentExpansionQa.Select(save.Catalog.Items.First(i=>i.FishingRod).Id);player.GetComponent<PlayerAvatar>().Facing.Face(Vector2.left);var fishing=player.GetComponent<PlayerFishing>();Check(fishing.Use(),"actual fishing cast");yield return Wait(3.2f);Check(fishing.Phase==FishingPhase.Bite,"actual fishing bite");Check(fishing.Use(),"actual fishing catch");yield return Wait(.6f);Check(Count(Sound.Cast)>0&&Count(Sound.Bite)>0&&Count(Sound.Catch)>0,"cast/bite/catch cues are distinct");
   var deathState=player.GetComponent<PlayerDeath>();var killDeadline=Time.realtimeSinceStartup+8;while(deathState.State==PlayerLife.Alive&&Time.realtimeSinceStartup<killDeadline){hp.ApplyDamage(hp.Maximum*4,true);yield return Wait(.3f);}Check(deathState.State==PlayerLife.Dead,"actual lethal damage entered death; state="+deathState.State+" hp="+hp.Current);Check(deathState.HomeRespawn(),"actual free home recovery");yield return Wait(.4f);Check(Count(Sound.PlayerDeath)>0&&Count(Sound.Revive)>0,"death/recovery cues confirmed by real lifecycle");
   // Every mapped production sound is also exercised through the actual voice service.
   foreach(Sound cue in Enum.GetValues(typeof(Sound))){AudioRuntime.Play(cue,player.transform.position);yield return Wait(.11f);}Check(runtime.GetComponentsInChildren<AudioSource>().Length==30,"all event playback uses fixed30sources");
   var cave=save.World.Map.Continental.Caves.First();var deep=cave.Rooms.OrderByDescending(r=>r.Depth).First();ContentExpansionQa.Move(deep.Center);yield return Wait(4.5f);Check(runtime.Landscape.Region==AudioRegion.Deep,"actual deep cavern position selects deep ambience");ContentExpansionQa.Move(Vector2.zero);save.Clock.Model.SetElapsed(save.Clock.Definition.DaySeconds+save.Clock.Definition.EveningSeconds+1);yield return Wait(4.5f);Check(runtime.Landscape.Region==AudioRegion.Night,"actual night clock selects night bed");
   var intro=Count(Sound.BossIntro);var phase=Count(Sound.BossPhase);var death=Count(Sound.BossDeath);var victory=Count(Sound.BossVictory);ContentExpansionQa.S.Clock.Model.SetElapsed(1);yield return BossProductionQa.Guard("Lifecycle");yield return Wait(4);Check(Count(Sound.BossIntro)>intro&&Count(Sound.BossPhase)>phase&&Count(Sound.BossDeath)>death&&Count(Sound.BossVictory)>victory,"real boss scheduler lifecycle emitted intro/phase/death/victory");
   // Event-schedule acceleration: 1,800 logical seconds, not a claim of 30 minutes listening.
   var sources=runtime.GetComponentsInChildren<AudioSource>().Length;for(var second=0;second<1800;second++){for(var i=0;i<20;i++)AudioRuntime.Play((Sound)(i%(int)Sound.BossIntro));if(second%30==0)yield return Wait(.01f);}Check(runtime.GetComponentsInChildren<AudioSource>().Length==sources,"1800logical-second burst simulation does not grow source pool");
   var current=ContentExpansionQa.S;Check(current.Save(),"isolated save commits");Check(current.Capture().Version==14,"Save14 retained");yield return SceneManager.LoadSceneAsync(SceneFlow.HomeScene);yield return Wait(.5f);Check(AudioRuntime.Current==runtime,"return home retains one owner");home=Object.FindFirstObjectByType<HomeScreen>();home.TryContinue();yield return Wait(2);Check(Object.FindObjectsByType<AudioRuntime>(FindObjectsSortMode.None).Length==1&&runtime.GetComponentsInChildren<AudioSource>().Length==30,"Continue does not duplicate music or pool");Check(peak<.999f,"captured final mix did not clip");Check(buffers>10&&power>1e-7,"actual Unity output buffers contain audio");
  }
 }
}
